const created = sdk.operation("northstar.app:operation.custom_receipt_check_create", {
  legalEntityId: event.legalEntityId,
  recordId: event.eventId,
  relations: { "northstar.app:relation.custom_receipt_check_goods_receipt": event.receiptId },
  values: { "northstar.app:field.custom_receipt_check_name": "Receipt check " + event.receiptId }
});
const record = created.readBack;
if (created.outcome !== "succeeded" || record === null) {
  return;
}
sdk.sleep(172800000);
const doneInput = { expectedRevision: record.revision, recordId: record.recordId };
const approved = sdk.requestApproval("Mark receipt check for receipt " + event.receiptId + " as Done", "northstar.app:operation.custom_receipt_check_action_done", doneInput);
if (approved) {
  sdk.operation("northstar.app:operation.custom_receipt_check_action_done", doneInput);
}

